(()=>{
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();
const seed=[
// Original low-stakes placement tasks: receptive and controlled productive skills.
['Первые фразы','oi','Что означает Oi!?',['Привет!','Спасибо!','До завтра!'],0,'Oi — дружеское приветствие.'],
['Знакомство','nome','Как сказать «Я Ана»?',['Eu sou Ana.','Eu estou Ana.','Eu tenho Ana.'],0,'Для имени используем sou: Eu sou Ana.'],
['Понимание сообщения','oi','Друг пишет: «Bom dia! Tudo bem?» Что он делает?',['Прощается до завтра','Здоровается и спрашивает, как дела','Называет свой адрес'],1,'Bom dia — доброе утро; Tudo bem? — как дела?'],
['Короткий ответ','oi','Напиши по-португальски «Привет».',null,['oi','ola'],'Oi! или Olá!'],
['Состояние и место','estar','Как сказать «Я сейчас дома»?',['Eu sou em casa.','Eu estou em casa.','Eu tenho casa agora.'],1,'Для местонахождения человека: estou em casa.'],
['Просьба','cafe','В кафе ты хочешь заказать воду. Выбери вежливую просьбу.',['Eu fui à água.','Água é ontem.','Uma água, por favor.'],2,'Por favor смягчает просьбу.'],
['Чтение объявления','horas','«A farmácia abre às nove e fecha às dezoito.» Когда открывается аптека?',['В 9:00','В 18:00','В полдень'],0,'Abre — открывается; às nove — в девять.'],
['Настоящее время','rotina','Вставь одно слово: Eu ___ português todos os dias. (изучаю)',null,['estudo'],'Eu estudo português todos os dias.'],
['События в прошлом','ontem','«Ontem fui ao mercado, mas não comprei nada.» Что произошло?',['Покупки запланированы на завтра','Вчера человек сходил на рынок, но ничего не купил','Человек каждый день покупает продукты'],1,'Fui и comprei описывают завершённые события; não ... nada — ничего.'],
['Сравнение','comparar','Выбери «Этот автобус дешевле, чем такси».',['Este ônibus é mais barato que o táxi.','Este ônibus é muito barato ontem.','Este ônibus é tão que táxi.'],0,'Mais barato que — дешевле, чем.'],
['Время и привычки','imperfeito','«Quando era criança, eu brincava na rua.» Речь идёт…',['об одном событии завтра','о привычке в детстве','о приказе играть'],1,'Era и brincava задают фон и привычку в прошлом.'],
['Прошедшее: свой ответ','ontem','Вставь форму ir: Ontem eu ___ ao mercado. (Вчера я сходил на рынок.)',null,['fui'],'Ontem eu fui ao mercado.'],
['Аргумент и оговорка','conectores','«Embora o curso seja curto, ele é útil.» Какая мысль передана?',['Курс полезен, несмотря на то что короткий','Курс полезен только из-за цены','Курс ещё не начался'],0,'Embora вводит уступку: хотя / несмотря на то что.'],
['Просьба с условием','condicional','Как вежливо попросить повторить?',['Você repetiu ontem?','Você poderia repetir, por favor?','Você repete nunca.'],1,'Poderia — мог бы: вежливая просьба.'],
['Понимание позиции','opiniao','«O transporte melhorou, porém ainda faltam ônibus à noite.» Что думает автор?',['Проблем больше нет','Ночных автобусов слишком много','Есть улучшение, но ночных автобусов не хватает'],2,'Porém — однако; ainda faltam — всё ещё не хватает.'],
['Будущая ситуация','subjuntivo','Вставь форму ter: Se eu ___ tempo amanhã, vou estudar. (Если завтра у меня будет время.)',null,['tiver'],'После se о возможном будущем: se eu tiver tempo.']
].map((v,i)=>({id:'pt-'+i,band:Math.floor(i/4),skill:v[0],lesson:v[1],q:v[2],options:v[3],answer:v[4],why:v[5]}));
const extra=[
[['Представиться','nome','Допиши имя: Eu ___ Ana.',['sou'],'Eu sou Ana.'],['Ответить на приветствие','oi','Допиши «Всё хорошо»: Tudo ___.',['bem'],'Tudo bem.']],
[['Просьба без вариантов','cafe','Допиши «пожалуйста»: Uma água, por ___.',['favor'],'Por favor — пожалуйста.'],['Сказать о себе','ter','Вставь ter для «я»: Eu ___ uma irmã.',['tenho'],'Eu tenho uma irmã.']],
[['Сравнение без вариантов','comparar','Вставь «дешевле»: Este ônibus é mais ___ que o táxi.',['barato'],'Mais barato que — дешевле, чем.'],['Рассказать о покупке','passado','Поставь comprar в прошлом: Ontem eu ___ pão.',['comprei'],'Ontem eu comprei pão.']],
[['Выразить мнение','opiniao','Вставь achar для «я»: Eu ___ que a cidade precisa de ônibus.',['acho'],'Eu acho que — я считаю, что.'],['Связать мысли','conectores','Вставь «но»: Quero sair, ___ está chovendo.',['mas'],'Mas — но.']]
];
const bank=[0,1,2,3].flatMap(b=>[...seed.filter(q=>q.band===b),...extra[b].map(v=>({band:b,skill:v[0],lesson:v[1],q:v[2],options:null,answer:v[3],why:v[4]}))].map((q,i)=>({...q,id:'v3-'+b+'-'+i})));
const labels=['Первые фразы','Бытовые основы','Рассказы о прошлом','Связные мысли'];
function begin(experience=''){return {version:3,course:'pt',experience,at:new Date().toISOString(),answers:[],done:false}}
function current(s){return !s||s.version!==3||s.done?null:bank[s.answers.length]}
function passed(answers){return answers.length===6&&answers.filter(a=>a.correct).length>=5&&answers.filter(a=>a.productive).length===3&&answers.filter(a=>a.productive).every(a=>a.correct)}
function submit(s,value){if(s.done)return s;const q=current(s);if(!q)return s;const correct=q.options?/^\d+$/.test(String(value))&&Number(value)===q.answer:q.answer.some(a=>norm(a)===norm(value));s.answers.push({id:q.id,band:q.band,skill:q.skill,lesson:q.lesson,productive:!q.options,answer:String(value).slice(0,250),correct});const count=s.answers.length;if(count%6===0)s.done=!passed(s.answers.slice(-6))||count===bank.length;return s}
function result(s){if(!s.done)throw Error('Placement incomplete');let mastered=-1;for(let b=0;b<4;b++){if(passed(s.answers.filter(a=>a.band===b)))mastered=b;else break}const comfortBand=s.experience==='С нуля'?0:Math.max(0,mastered-1),lesson=['oi','estar','ontem','conectores'][comfortBand];return {version:3,course:'pt',at:new Date().toISOString(),level:mastered<0?'Начинаем с первых фраз':labels[mastered]+' · проверены отдельные навыки',mastered,ceiling:mastered===3,lesson,results:s.answers,summary:mastered<0?'Начнём с приветствий и простых ответов. Ничего знать заранее не нужно.':'Получились отдельные задания: '+labels[mastered]+'. Это ещё не значит, что вся тема освоена. Начнём с более простой опоры и будем двигаться по порядку.',testedBand:Math.floor((s.answers.length-1)/6)}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function page(u){const s=u.placementDraft,q=current(s);if(!s||s.version!==3||s.done)return `<div class="narrow panel"><div class="eyebrow">Бразильский португальский · точка старта</div><h1>Найдём комфортную сложность</h1><p>От 6 до 24 заданий: слова, бытовые сообщения, грамматика и короткие ответы без вариантов. Примерно 7–12 минут. Можно сразу начать с нуля без проверки.</p><p>Начинаем с простого. Чтобы усложнить задания, нужны пять верных ответов из шести и все три ответа без вариантов. Даже хороший результат сначала ведёт к более простой опоре. Ошибка — подсказка для маршрута, а не плохая оценка. Можно выбрать «Пока не знаю».</p><p class="small">Задания составлены для Bora с ориентацией на описания навыков CEFR. Проверка не стандартизирована: она не оценивает произношение, свободную речь или готовность к Celpe-Bras. Не пользуйся переводчиком; разбор увидишь в конце.</p>${u.diagnosis?`<div class="notice">Последний ориентир: ${esc(u.diagnosis.summary)}</div><a href="#result">Посмотреть результат</a>`:''}<button class="btn" id="placement-begin">Начать проверку →</button><p><button class="btn alt" id="placement-zero">Я с нуля — сразу к первым фразам</button></p></div>`;
return `<div class="narrow panel"><div class="eyebrow">Задание ${s.answers.length+1} из максимум 24 · ${esc(q.skill)}</div><progress value="${s.answers.length}" max="24" aria-label="Пройдено заданий"></progress><h1>${esc(q.q)}</h1>${q.options?`<div class="options">${q.options.map((o,i)=>`<button class="option" data-placement-answer="${i}">${esc(o)}</button>`).join('')}</div>`:`<form id="placement-write"><label>Твой ответ<input name="answer" maxlength="250" autocomplete="off" required></label><button class="btn">Ответить →</button></form>`}<button class="btn alt" id="placement-unknown">Пока не знаю</button><p class="small">Ответы сохраняются в аккаунте. Если уйдёшь со страницы, продолжим с этого места.</p><a href="#home">Продолжить позже</a></div>`}
function resultPage(u){const d=u.diagnosis;if(d?.version!==3)return `<div class="narrow panel"><h1>Обновим точку старта</h1><p>Прежняя короткая проверка могла завысить стартовую сложность. Обновлённая проверка требует больше самостоятельных ответов и выбирает более осторожное начало.</p><a class="btn" href="#diagnosis">Пройти новую проверку</a><p><a class="btn alt" data-comfort-start="oi" href="#courses/pt/oi">Начать с простого</a></p></div>`;const lesson=window.BoraCourses[0].lessons.find(l=>l.id===d.lesson);return `<div class="narrow panel"><div class="eyebrow">Твой предварительный маршрут</div><h1>${esc(d.level)}</h1><p>${esc(d.summary)}</p><div class="notice">Начни с «${esc(lesson?.title||'Начать разговор')}». Ранее пройденные уроки сохраняются. Можно открыть любой урок или повторить основы.</div><div class="example"><p class="small">Посмотри пример стартового урока. Если он непонятен, выбери начало с первых фраз.</p><strong lang="pt-BR">${esc(lesson?.examples[0][0]||'Oi!')}</strong><p>${esc(lesson?.examples[0][1]||'Привет!')}</p></div><a class="btn yellow" data-comfort-start="${esc(d.lesson)}" href="#courses/pt/${esc(d.lesson)}">Начать рекомендованный урок →</a><p class="small">Это ориентир для письменных заданий, не сертификат CEFR. ${d.ceiling?'Ты достиг верхней границы этой проверки; более высокий уровень здесь не измеряется.':''} Говорение, аудирование и свободное письмо требуют отдельной оценки.</p><p><a class="btn alt" data-comfort-start="oi" href="#courses/pt/oi">Лучше начну с самого простого</a></p><p class="small">Если первый урок сложен, нажми «Слишком сложно» в уроке. Можно менять маршрут без потери результатов.</p><h2>Что получилось и что повторить</h2>${d.results.map(r=>{const q=bank.find(q=>q.id===r.id);return `<details><summary>${r.correct?'✓':'↻'} ${esc(r.skill)}</summary><p>${esc(q.q)}</p><p>Твой ответ: ${esc(r.answer==='-1'?'Пока не знаю':q.options?.[Number(r.answer)]||r.answer)}</p><p>${esc(q.why)}</p>${!r.correct?`<a href="#courses/pt/${esc(r.lesson)}">Потренировать тему →</a>`:''}</details>`}).join('')}<p><a href="#courses/pt">Посмотреть всю программу</a> · <a href="#diagnosis">Повторить проверку</a></p></div>`}
function bind(u,save,render){const $=s=>document.querySelector(s);if($('#placement-begin'))$('#placement-begin').onclick=()=>{u.placementDraft=begin(u.experience);save();render()};if($('#placement-zero'))$('#placement-zero').onclick=()=>{if(u.diagnosis)u.diagnosisHistory=[...(u.diagnosisHistory||[]),u.diagnosis].slice(-10);u.placementDraft=null;u.diagnosis={version:3,course:'pt',level:'Начало с нуля · твой выбор',lesson:'oi',results:[],summary:'Начинаем с приветствий, без оценки уровня.'};u.learningPath={lesson:'oi',reason:'self-chosen-basics'};u.simpleExplanations=true;if(u.courseProgress?.['pt/oi']){u.courseProgress['pt/oi'].stage=0;if(u.courseProgress['pt/oi'].guided)u.courseProgress['pt/oi'].guided.index=0;}save();location.hash='courses/pt/oi'};const answer=v=>{if(!u.placementDraft||u.placementDraft.done)return;submit(u.placementDraft,v);if(u.placementDraft.done){if(u.diagnosis)u.diagnosisHistory=[...(u.diagnosisHistory||[]),u.diagnosis].slice(-10);u.diagnosis=result(u.placementDraft);u.program='pt';u.learningPath={lesson:u.diagnosis.lesson,reason:'placement-v3'};save();location.hash='result'}else{save();render();window.scrollTo(0,0)}};document.querySelectorAll('[data-placement-answer]').forEach(b=>b.onclick=()=>answer(b.dataset.placementAnswer));if($('#placement-unknown'))$('#placement-unknown').onclick=()=>answer('-1');if($('#placement-write'))$('#placement-write').onsubmit=e=>{e.preventDefault();answer(new FormData(e.target).get('answer'))}}
window.BoraPlacement={begin,current,submit,result,page,resultPage,bind,bank,norm};
})();
